INSERT INTO articulos (
  slug, titulo, extracto, contenido, imagen_destacada, estado, metadata, created_at, updated_at, categoria_id, autor_id
) VALUES (
  'las-estatuas-de-accion-colectiva', 'Las Estatuas de Acción Colectiva', 'Dinámica de congelamiento dramático y trabajo en equipo donde los scouts representan escenas de campamento inmóviles.', '<h2>📜 Descripción de Las Estatuas de Acción Colectiva</h2>
<p><b>Las Estatuas de Acción Colectiva</b> es una dinámica de expresión corporal, equilibrio kinésico y representación de escenas de campamento. Organizados en patrullas, los scouts deben congelar su postura al unísono cuando el dirigente exclama <i>''¡Estatuas en acción!''</i>, representando cooperativamente una escena dramática activa (ej. <i>''Un equipo cruzando un río con un herido''</i>, <i>''El armado de una torre de pionerismo''</i> o <i>''Una emergencia por mal tiempo''</i>).</p>
<p>Esta actividad ejercita el control postural, la imaginación escénica y la coordinación del movimiento en Manada, Compañía, Tropa, Avanzada y Clan.</p>

<h2>🎲 ¿Cómo se juega Las Estatuas de Acción Colectiva?</h2>
<p>Para llevar a cabo la dinámica con solemnidad y alegría, los dirigentes deben seguir estos pasos:</p>
<ul>
  <li><b>Consigna de Escena:</b> El animador anuncia la escena de campamento o aventura que la unidad debe interpretar.</li>
  <li><b>Movimiento de Preparación:</b> Las patrullas se desplazan libremente por el área dramatizando las acciones previas.</li>
  <li><b>El Congelamiento Instantáneo:</b> Al silbatazo o grito de <i>''¡Estatuas!''</i>, todos se detienen de inmediato congelando sus rostros y músculos.</li>
  <li><b>Inspección de la Galería:</b> El jurado recorre las ''estatuas'' evaluando la postura, la expresividad y la inmovilidad total.</li>
  <li><b>Rotación de Temas:</b> Se premia la mejor escultura viviente y se cambia a un nuevo escenario scout.</li>
</ul>

<h2>🏆 Cómputo de Puntos y Condición de Victoria de Las Estatuas de Acción Colectiva</h2>
<p>La actividad valora la expresividad dramática y el control físico en el Tally:</p>
<ul>
  <li><b>Mayor Expresividad Corporal:</b> Otorgar 5 puntos al equipo que logre la pose estatuaria más dramática e ingeniosa.</li>
  <li><b>Inmovilidad Absoluta:</b> Otorgar 3 puntos a la patrulla que no parpadee ni se mueva durante la inspección.</li>
  <li><b>Cohesión de Grupo:</b> Otorgar 3 puntos a la escultura que integre armónicamente a todos sus integrantes en la escena.</li>
</ul>', '/uploads/las-estatuas-de-accion-colectiva.webp', 'publicado', '{"areas": ["creatividad", "corporalidad"], "unidades": ["manada", "compañía", "tropa", "avanzada", "clan"], "duracion": "20 minutos", "cantidad": "04 participantes", "lugares": ["Interior", "Salón", "Exterior", "Campo Abierto"], "materiales": ["Sin Materiales"], "objetivos": ["Fomentar la comunicación e interpretación", "Estimular la agilidad mental", "Desarrollar la motricidad", "Trabajo en equipo"], "justificacion_areas": "Las Estatuas de Acción Colectiva potencia la creatividad al requerir la traducción inmediata de situaciones complejas a esculturas humanas tridimensionales. Desarrolla la corporalidad al afianzar el dominio muscular, el equilibrio estático, el esquema corporal y la flexibilidad postural desde Manada hasta Clan.", "variaciones": "<b>Estatuas de Sombras en la Fogata:</b> Realizar las esculturas proyectadas tras una sábana con linternas nocturnas.<br><b>Estatuas Encadenadas:</b> Cada estatua debe estar en contacto físico directo con un compañero de patrulla.<br><b>Estatuas con Pañolín Cruzado:</b> Congelar la pose sosteniendo el pañolín scout como elemento de la escena.", "recomendaciones": "Asegurar que las poses sean seguras y no generen caídas o pérdidas brutales de equilibrio. Estimular la soltura dramática.", "objetivos_educativos": [{"id": "52b5580a-7d0f-454f-b2ae-0d3318129165", "area": "Creatividad", "unidad": "Manada", "texto": "Canto, bailo y preparo actuaciones con mis amigos de la Manada.", "como_se_cumple": "Participando en la creación de estatuas colectivas e interpretación de escenas."}, {"id": "d9ebcd96-c9cf-444f-94fb-5569110a1b99", "area": "Corporalidad", "unidad": "Manada", "texto": "Participo en actividades que me ayudan a tener un cuerpo cada vez más fuerte, ágil, veloz y flexible.", "como_se_cumple": "Dominando el equilibrio estático y el control muscular al congelar la pose de estatua."}, {"id": "14b82459-ac31-4496-a875-8e9bd5666030", "area": "Creatividad", "unidad": "Manada", "texto": "En las actividades que hago se nota lo que pienso y siento.", "como_se_cumple": "Expresando emociones y gestos en la escultura humana."}, {"id": "626a313e-0407-4cfd-b714-c6aa6e51738c", "area": "Corporalidad", "unidad": "Manada", "texto": "Manejo cada vez mejor mis brazos, piernas, manos y pies.", "como_se_cumple": "Ejercitando la agilidad y el tono muscular en posturas divertidas de extremidades."}, {"id": "d581cfa7-db1f-4b08-b4d3-525b23e418ea", "area": "Creatividad", "unidad": "Compañía", "texto": "Participo con entusiasmo en las actividades artísticas de mi Compañía.", "como_se_cumple": "Liderando composiciones estatuarias en la patrulla."}, {"id": "0ba0d3c3-a50a-4a04-8981-601dc7746dd6", "area": "Corporalidad", "unidad": "Compañía", "texto": "Sé lo que puedo y no puedo hacer con mi cuerpo.", "como_se_cumple": "Sosteniendo posturas corporales firmes y armónicas durante la inspección."}, {"id": "0009f64a-0654-46bf-b6fc-7b9d7f278485", "area": "Creatividad", "unidad": "Compañía", "texto": "Puedo analizar una situación desde distintos puntos de vista.", "como_se_cumple": "Representando escenas dramáticas de campamento desde perspectivas estéticas diversas."}, {"id": "fb56310a-a9cf-46e3-9c34-c4643f6b9035", "area": "Corporalidad", "unidad": "Compañía", "texto": "Respeto mi cuerpo y el de los demás.", "como_se_cumple": "Adaptando las poses a la capacidad física y flexibilidad de las pares."}, {"id": "39eaf1aa-f703-4fd0-a4b3-b9756dc30539", "area": "Creatividad", "unidad": "Tropa", "texto": "Participo con entusiasmo en las actividades artísticas de mi Tropa.", "como_se_cumple": "Aportando creatividad tridimensional en las representaciones de la Tropa."}, {"id": "4946a6aa-4a9f-4e7b-89a3-cb5249db8257", "area": "Corporalidad", "unidad": "Tropa", "texto": "Sé lo que puedo y no puedo hacer con mi cuerpo.", "como_se_cumple": "Controlando la estabilidad y alineación física al mantenerse inmóvil."}, {"id": "6e910d1c-7021-49a5-9ece-637f480a1ec7", "area": "Creatividad", "unidad": "Tropa", "texto": "Expreso por distintos medios mis intereses y aptitudes artísticas.", "como_se_cumple": "Diseñando figuras estatuarias complejas y expresivas."}, {"id": "91473f71-9345-4bcf-bfc7-dea709d12361", "area": "Corporalidad", "unidad": "Tropa", "texto": "Respeto mi cuerpo y el de los demás.", "como_se_cumple": "Respetando el propio equilibrio muscular y la coordinación del equipo."}, {"id": "d252cb51-c224-4528-90b3-e0288aa343dd", "area": "Creatividad", "unidad": "Avanzada", "texto": "Comparto con los demás mis inquietudes, aspiraciones y creaciones artísticas.", "como_se_cumple": "Compartiendo con la Avanzada la composición dramática e interpretación estatuaria colectiva."}, {"id": "e1c20419-a6d0-48b2-91e8-20a96d2b11c3", "area": "Corporalidad", "unidad": "Avanzada", "texto": "Asume la parte de responsabilidad que le corresponde en el desarrollo armónico de su cuerpo.", "como_se_cumple": "Demostrando dominio corporal pleno e inmovilidad estatuaria en la Avanzada."}, {"id": "91e60eba-e267-4d1a-b27b-ef61a7b03b31", "area": "Creatividad", "unidad": "Clan", "texto": "Expresa lo que piensa y siente a través de distintos medios, creando en los ambientes en que actúa espacios gratos que faciliten el encuentro y el perfeccionamiento entre las personas.", "como_se_cumple": "Fomentando la expresión artística y la integración en representaciones del Clan Rover."}, {"id": "bc8f595b-6949-4f2e-9304-86a2306449e1", "area": "Corporalidad", "unidad": "Clan", "texto": "Asume la parte de responsabilidad que le corresponde en el desarrollo armónico de su cuerpo.", "como_se_cumple": "Dominando el control motor fino y el acondicionamiento físico en el Clan."}]}'::jsonb, NOW(), NOW(), NULL, NULL
);

